// Match recorded effect identity, not name/amount guesses. No combat re-evaluation.
import {ATTR,SKILLS} from './expedition-data.mjs';
const stats={weaponDamage:'持械附加法术伤害基值',corrosion:'持续伤害基值',cover:'援护许可',regeneration:'每回合缓释恢复',...ATTR,defense:'全防御检定',skill:'攻击技能等级',defenseSkill:'防御技能等级',armor:'护甲',actions:'行动次数',extraActionLimit:'额外行动限制',healingBlock:'自动救护禁疗'};
export function effectOrigins(events){const origins=new Map();events.forEach((e,index)=>{if(['effect','ward-link'].includes(e.type)&&e.detail.effectId)origins.set(e.detail.effectId,{index,source:e.actor,targets:e.targets,...(e.type==='ward-link'?{environmental:true}:{})});});return origins;}
export function sourceTrace(group,origins){
 const cleanses=group.events.filter(e=>e.type==='cleanse'||e.type==='dispel');
 const removals=cleanses.map(e=>({eventId:e.id,title:`${e.units.find(u=>u.id===e.targets[0])?.name||e.targets[0]} · ${e.type==='dispel'?'破印':'净化'}`,check:e.detail.rule,effects:e.detail.removed.map(s=>{const origin=origins.get(s.effectId),matched=origin&&origin.source===s.source&&origin.targets.includes(e.targets[0])&&origin.index<group.start;return {side:'被移除',recipient:e.units.find(u=>u.id===e.targets[0])?.name||e.targets[0],source:s.sourceName||e.units.find(u=>u.id===s.source)?.name||s.source,name:s.component||s.name,stat:stats[s.stat]||s.stat,value:s.value,origin:matched?origin.index:null};})}));
 if(cleanses.some(e=>e.type==='cleanse'))return removals;
 const passive=group.events.filter(e=>e.type==='harm'||e.type==='heal'&&e.detail.passive);
 if(passive.length)return passive.map(e=>({eventId:e.id,title:`${e.units.find(u=>u.id===e.targets[0])?.name||e.targets[0]} · ${e.type==='harm'?'持续伤害':'缓释恢复'}`,check:e.type==='harm'?`基值${e.detail.base} / 法术抗性${e.detail.resistance}% / 实扣${e.detail.actual} / 溢出${e.detail.overkill}；不占普通行动、不重复扣材料`:`恢复 ${e.detail.actual} / 未生效 ${e.detail.overheal}；不占普通行动，不再次扣材料`,effects:(e.detail.sources||[]).map(s=>{const origin=origins.get(s.effectId),matched=origin&&origin.source===s.source&&origin.targets.includes(e.targets[0])&&origin.index<group.start;return {side:e.type==='harm'?'受蚀者':'恢复者',recipient:e.units.find(u=>u.id===e.targets[0])?.name||e.targets[0],source:e.units.find(u=>u.id===s.source)?.name||s.source,name:s.component||s.name,stat:stats[s.stat]||s.stat,value:s.value,origin:matched?origin.index:null};})}));
 const queue=group.events.find(e=>e.type==='initiative');
 if(queue)return queue.detail.order.map(o=>({eventId:queue.id,title:`${o.actor} · 第${o.ordinal}/${o.total}次行动`,check:o.initiative?`${o.initiative.name} · ${o.initiative.formula} = 均值 ${o.mean}；支付${o.initiative.cost}法力${o.initiative.reason?'，'+o.initiative.reason:''}；基础实掷${o.base} ÷ ${1+.6*(o.ordinal-1)} = ${o.value.toFixed(2)}`:o.mean===undefined?`排序值 ${o.value}`:`敏捷 ${o.agi} ×2 + 感知 ${o.per} = 均值 ${o.mean}；基础实掷 ${o.base} ÷ ${1+.6*(o.ordinal-1)} = ${o.value.toFixed(2)}`,effects:(o.sources||[]).filter(s=>(o.initiative?.chosen==='foresight'?['int','per','actions']:['agi','per','actions']).includes(s.stat)).map(s=>{const origin=origins.get(s.effectId),matched=origin&&origin.source===s.source&&origin.targets.includes(o.actorId)&&origin.index<group.start;return {side:'行动者',recipient:o.actor,source:queue.units.find(u=>u.id===s.source)?.name||s.source,name:s.component||s.name,stat:stats[s.stat]||s.stat,value:s.value,origin:matched?origin.index:null};})}));
 const attacks=group.events.filter(e=>e.type==='attack'),events=attacks.length?attacks:group.events.filter(e=>e.type==='cast');
 const interceptions=group.events.filter(e=>['intercept','intercept-skip'].includes(e.type)).map(e=>{
  const d=e.detail,name=id=>e.units.find(u=>u.id===id)?.name||id,identity=d.cover,origin=origins.get(identity.effectId),matched=origin&&origin.source===identity.source&&origin.targets.includes(d.protected)&&origin.index<group.start;
  return {eventId:e.id,title:name(d.guardian)+' → '+name(d.protected)+' · 援护',check:e.type==='intercept'?`援护 ${d.reaction} / 均值 ${d.reactionMean} vs 难度 ${d.difficulty}（攻击 ${d.attack}×0.8向上取整）；${d.success?'成功接招':'未及接招'}，支付${d.cost}法力；之后仍正常防御`:`${d.reason}；本次支付0`,effects:[{side:'援护许可',recipient:name(d.protected),source:name(identity.source),name:identity.component,stat:stats.cover,value:identity.value,origin:matched?origin.index:null},...(d.sources||[]).map(s=>{const o=origins.get(s.effectId),ok=o&&o.source===s.source&&o.targets.includes(d.guardian)&&o.index<group.start;return {side:'援护者',recipient:name(d.guardian),source:name(s.source),name:s.component||s.name,stat:stats[s.stat]||s.stat,value:s.value,origin:ok?o.index:null};})]};
 });
 return [...removals,...interceptions,...events.map(e=>{
 const name=id=>e.units.find(u=>u.id===id)?.name||id;
 const sources=(items,recipient,side)=>(items||[]).map(s=>{const origin=origins.get(s.effectId),matched=origin&&origin.source===s.source&&origin.targets.includes(recipient)&&origin.index<group.start;
 return {side,recipient:name(recipient),source:name(s.source),name:s.component||s.name,stat:stats[s.stat]||s.stat,value:s.value,origin:matched?origin.index:null,...(origin?.environmental?{environmental:true}:{})};});
 return {eventId:e.id,title:e.type==='attack'?`${name(e.actor)} → ${name(e.targets[0])}`:`${name(e.actor)} · ${SKILLS[e.detail.skill]?.name||'施放'}`,check:e.type==='attack'?`攻击均值 ${e.detail.attackMean} / 实掷 ${e.detail.attack}；防御均值 ${e.detail.defenseMean} / 实掷 ${e.detail.defense}；${e.detail.grade}，实扣生命 ${e.detail.actual}`:`施放均值 ${e.detail.mean}`,effects:[...sources(e.detail.sources,e.actor,'施放者'),...sources(e.detail.targetSources,e.targets[0],'防御者')]};
 })];
}
